    private List<Vector2> AverageStroke(List<Vector2> first, List<Vector2> second)
    {
        List<Vector2> normalizedFirst = GestureNormalizationHelper.ProcessPoints(first, 64, 250f);
        List<Vector2> normalizedSecond = GestureNormalizationHelper.ProcessPoints(second, 64, 250f);
        int count = Mathf.Max(normalizedFirst.Count, normalizedSecond.Count);
        var averaged = new List<Vector2>(count);
        for (int i = 0; i < count; i++)
        {
            Vector2 firstPoint = i < normalizedFirst.Count ? normalizedFirst[i] : normalizedFirst[normalizedFirst.Count - 1];
            Vector2 secondPoint = i < normalizedSecond.Count ? normalizedSecond[i] : normalizedSecond[normalizedSecond.Count - 1];
            averaged.Add((firstPoint + secondPoint) / 2f);
        }
        return averaged;
    }
